html:
{%- set g = get_ghs_label_data(doc.name, "4x6") -%}
{%- set geo = g.geo -%}
<style>
	.print-format { page-width: {{ geo.w }}mm; page-height: {{ geo.h }}mm; margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; padding: 0 !important; width: {{ geo.w }}mm !important; max-width: {{ geo.w }}mm !important; min-height: 0 !important; }
	.ghs, .ghs div { box-sizing: border-box; }
	.ghs { position: relative; width: {{ geo.w }}mm; height: {{ geo.h - 0.2 }}mm; overflow: hidden; font-family: Arial, Helvetica, sans-serif; color: #000; background: #fff; page-break-after: always; }
	.ghs .box { position: absolute; left: {{ geo.pad_x }}mm; width: {{ geo.body_w }}mm; overflow: hidden; }
	.ghs .hdr { top: {{ geo.pad_top }}mm; height: {{ geo.header_h }}mm; border-bottom: {{ geo.rule }}mm solid #000; }
	.ghs .pname { position: absolute; left: 0; top: 0; width: {{ geo.body_w * 0.72 }}mm; font-weight: bold; line-height: 1.05; }
	.ghs .pref { font-size: {{ geo.pref_pt }}pt; font-weight: normal; line-height: 1.1; }
	.ghs .signal { position: absolute; right: 0; top: 0.6mm; font-size: {{ geo.signal_pt }}pt; font-weight: 900; letter-spacing: 0.3pt; white-space: nowrap; line-height: 1; }
	.ghs .body { top: {{ geo.body_top }}mm; height: {{ geo.body_h }}mm; }
	.ghs .picto { position: absolute; display: block; margin: 0; padding: 0; max-width: none !important; }
	.ghs .stmts { position: absolute; top: 0; right: 0; line-height: 1.15; }
	.ghs .stmts .h { display: block; margin: 0; }
	.ghs .stmts .p { display: block; margin: 0.4em 0 0 0; }
	.ghs .ftr { bottom: {{ geo.pad_bottom }}mm; height: {{ geo.footer_h }}mm; border-top: {{ geo.rule * 0.75 }}mm solid #000; font-size: {{ geo.footer_pt }}pt; line-height: 1.18; padding-top: 0.5mm; }
	.ghs .ftr .l { position: absolute; left: 0; top: 0.6mm; width: {{ geo.body_w * 0.7 }}mm; }
	.ghs .ftr .r { position: absolute; right: 0; top: 0.6mm; text-align: right; white-space: nowrap; }
	.ghs .missing { position: absolute; left: {{ geo.pad_x }}mm; top: {{ geo.pad_top }}mm; width: {{ geo.body_w }}mm; border: 0.5mm solid #c00; color: #c00; padding: 1.5mm; font-size: {{ geo.notice_pt }}pt; line-height: 1.2; }
	.ghs .missing ul { margin: 0.5mm 0 0 3.5mm; padding: 0; }
</style>
<div class="ghs">
{%- if g.missing -%}
	<div class="missing">
		<b>{{ _("GHS label not printed: this SDS record is missing required label elements.") }}</b>
		<div style="color:#000; margin-top:0.5mm">{{ doc.name }} {{ doc.product_name or "" }}</div>
		<ul>{%- for m in g.missing -%}<li>{{ m }}</li>{%- endfor -%}</ul>
	</div>
{%- else -%}
	<div class="box hdr">
		<div class="pname" style="font-size:{{ g.name_pt }}pt">{{ doc.product_name }}{% if doc.product_reference_number %}<div class="pref">{{ doc.product_reference_number }}</div>{% endif %}</div>
		{%- if g.signal -%}<div class="signal">{{ g.signal | upper }}</div>{%- endif -%}
	</div>
	<div class="box body">
		{%- for p in g.pictograms -%}
		<img class="picto" src="{{ p.src }}" alt="{{ p.code }}" style="left:{{ p.left }}mm; top:{{ p.top }}mm; width:{{ p.size }}mm; height:{{ p.size }}mm">
		{%- endfor -%}
		<div class="stmts" style="left:{{ g.text_left }}mm; top:{{ g.text_top }}mm; right:{{ g.text_pad }}mm; font-size:{{ g.font_pt }}pt">
			{%- for h in g.hazards -%}<span class="h">{{ h }}</span>{%- endfor -%}
			{%- if g.workplace -%}<span class="p"><b>{{ g.see_sds }}</b></span>
			{%- elif g.precautions -%}<span class="p"><b>{{ _("Precautions:") }}</b> {{ g.precautions | join(" ") }}</span>{%- endif -%}
			{%- if not g.hazardous -%}<span class="h">{{ _("Not classified as hazardous under GHS. See SDS for handling information.") }}</span>{%- endif -%}
		</div>
	</div>
	<div class="box ftr">
		<div class="l">
			<b>{{ doc.manufacturer_name }}</b>, {{ g.address }}<br>
			{%- if doc.man_phone -%}{{ _("Tel") }} {{ doc.man_phone }}{%- endif -%}
			{%- if doc.man_phone and doc.emergency_phone %} &nbsp;|&nbsp; {% endif -%}
			{%- if doc.emergency_phone -%}<b>{{ _("Emergency") }} {{ doc.emergency_phone }}</b>{%- endif -%}
		</div>
		<div class="r">
			{{ doc.name }}{% if doc.version_date %}<br>{{ _("SDS rev") }} {{ frappe.format(doc.version_date, {"fieldtype": "Date"}) }}{% endif %}<br>
			<b>{% if g.workplace %}{{ _("Workplace label: read the SDS") }}{% else %}{{ _("Read the SDS before use") }}{% endif %}</b>
		</div>
	</div>
{%- endif -%}
</div>
